import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int t = 1;
        while (t-- > 0) {
            int n = readInt(dis);
            int a1 = readInt(dis);
            int a3 = readInt(dis);
            int a2 = readInt(dis);
            int b1 = readInt(dis);
            int b3 = readInt(dis);
            int b2 = readInt(dis);
            int min = 0;
            int max = 0;
            if (a1 > b3)
                max += b3;
            else
                max += a1;
            if (a2 > b1)
                max += b1;
            else
                max += a2;
            if (a3 > b2)
                max += b2;
            else
                max += a3;
            if (a1 > b2 + b1)
                min += Math.max(a1 - (b2 + b1), 0);
            if (a2 > b3 + b2)
                min += Math.max(a2 - (b3 + b2), 0);
            if (a3 > b1 + b3)
                min += Math.max(a3 - (b1 + b3), 0);
            System.out.println(min + " " + max);
        }
    }

    private static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        boolean neg = false;
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        if (c == '-') {
            neg = true;
            c = dis.read();
        }
        do {
            ret = ret * 10 + c - '0';
            c = dis.read();
        } while (c >= '0' && c <= '9');
        return neg ? -ret : ret;
    }
}
